/* Ngữ pháp B2 · Upper Intermediate — sinh tự động bởi tools/build-grammar.py (npm run build:grammar), đừng sửa tay */
(window.FA_GRAMMAR_LESSONS = window.FA_GRAMMAR_LESSONS || {})["B2"] = [{"n":1,"title":"Articles: generic & zero article","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Ở trình độ cao, lỗi mạo từ không còn là chọn a hay an mà là quyết định có dùng the hay để trống. Khi nói về cả một loại hoặc một khái niệm, tiếng Anh thường dùng danh từ số nhiều hoặc danh từ không đếm được mà không có mạo từ. Khi nói về một đối tượng cụ thể mà người đọc nhận ra được, mới dùng the. Ngoài ra có một nhóm cụm cố định không bao giờ dùng mạo từ."},{"p":"Cấu trúc chính: danh từ số nhiều không mạo từ (nói chung) | the + danh từ (đã xác định)"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Computers have changed education, but the computer in this lab is broken. (Nói về cả loại hoặc khái niệm | Nói về một đối tượng xác định | Cụm cố định không mạo từ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nói về cả loại hoặc khái niệm: Dùng danh từ số nhiều hoặc danh từ không đếm được, không có mạo từ. (Children learn languages quickly.)"},{"p":"Nói về một đối tượng xác định: Dùng the khi ngữ cảnh đã làm rõ là cái nào. (The children in this class are bilingual.)"},{"p":"Cụm cố định không mạo từ: Nói về chức năng chứ không về toà nhà hay vật cụ thể. (go to school / in hospital / by car / at home)"},{"p":"Tên riêng và địa danh: Phần lớn tên riêng không có mạo từ, nhưng tên sông, dãy núi, nhóm đảo và một số quốc gia thì có the. (Vietnam / the Mekong / the Philippines)"},{"p":"Ghi nhớ: Phân biệt cách nói về cả loại, cách nói về một đối tượng xác định và những danh từ không cần mạo từ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: danh từ số nhiều không mạo từ (nói chung) | the + danh từ (đã xác định)"},{"table":[["Nhóm cấu trúc","Công thức / Quy tắc","Ví dụ"],["Nghĩa khái quát","danh từ số nhiều hoặc không đếm được, không mạo từ","Books are expensive. / Water is essential."],["Nghĩa xác định","the + danh từ số ít hoặc số nhiều","The books on that shelf are mine."],["Khái quát bằng số ít","the + danh từ số ít, giọng học thuật","The smartphone has transformed communication."],["Không mạo từ trong cụm cố định","go to bed, at work, by train, in prison","She goes to work by bus."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Phân biệt nghĩa khái quát và nghĩa xác định: Cả loại thì để trống mạo từ; đối tượng cụ thể thì dùng the. (Computers are fast. ↔ The computer is broken.)"},{"p":"02. Kiểm tra danh từ trừu tượng: Các khái niệm như education, happiness, research không dùng the khi mang nghĩa chung. (Education is a right.)"},{"p":"03. Nhớ nhóm cụm cố định: Khi danh từ chỉ chức năng của nơi đó thì không có mạo từ; khi chỉ toà nhà cụ thể thì có the. (in hospital (đang điều trị) ↔ at the hospital (ở toà nhà đó))"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Khái quát và xác định","Computers have changed education, but the computer in this lab is broken.\n(Máy tính đã làm thay đổi giáo dục, nhưng chiếc máy tính trong phòng này thì hỏng.)","Vế đầu nói về cả loại nên không có mạo từ; vế sau nói về một chiếc cụ thể nên dùng the."],["Danh từ trừu tượng","Research on sleep has grown rapidly in recent years.\n(Nghiên cứu về giấc ngủ phát triển nhanh trong những năm gần đây.)","Research và sleep là danh từ trừu tượng mang nghĩa chung nên không dùng the."],["Khái quát bằng số ít","The smartphone has transformed the way we communicate.\n(Điện thoại thông minh đã thay đổi cách chúng ta giao tiếp.)","Dạng the cộng danh từ số ít mang nghĩa khái quát về cả loại phát minh, thường gặp trong văn học thuật."],["Cụm chỉ chức năng","Her son is in hospital, so she visits the hospital every evening.\n(Con trai cô ấy đang nằm viện nên tối nào cô cũng tới bệnh viện.)","In hospital nói về việc điều trị; the hospital nói về toà nhà cụ thể."],["Phương tiện","I go to work by bus, but today I took the bus that goes past the market.\n(Tôi đi làm bằng xe buýt, nhưng hôm nay tôi đi chuyến chạy qua chợ.)","By bus là cụm cố định chỉ phương thức; the bus chỉ một chuyến cụ thể."],["Địa danh","We travelled through Vietnam and sailed along the Mekong.\n(Chúng tôi đi khắp Việt Nam và xuôi theo sông Mê Kông.)","Tên quốc gia thường không có mạo từ, nhưng tên sông thì có the."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Cùng một danh từ, hai cách dùng"},{"table":[["Cụm từ","Nghĩa","Ví dụ"],["in hospital","đang nằm viện điều trị","He has been in hospital for a week."],["at the hospital","ở toà nhà bệnh viện","I met her at the hospital."],["go to school","đi học","My children go to school nearby."],["go to the school","đến ngôi trường đó vì việc khác","I went to the school to meet the head."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The computers have changed the education. → Đã sửa: Computers have changed education. — Cả hai danh từ đều mang nghĩa khái quát nên không dùng the."},{"p":"Chưa đúng: She goes to the work by the bus. → Đã sửa: She goes to work by bus. — To work và by bus là cụm cố định không dùng mạo từ."},{"p":"Chưa đúng: The research shows that the sleep is important. → Đã sửa: Research shows that sleep is important. — Danh từ trừu tượng mang nghĩa chung không dùng the."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Câu nói về cả loại hay về một đối tượng xác định."},{"p":"Danh từ trừu tượng mang nghĩa chung không có the."},{"p":"Cụm cố định chỉ chức năng không có mạo từ."},{"p":"Tên riêng dùng mạo từ đúng theo nhóm."}]}],"id":"b2-01"},{"n":2,"title":"Verb patterns: meaning change","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Phần lớn động từ chỉ chấp nhận một dạng thức ở phía sau, nhưng có một nhóm nhỏ đi được với cả hai và nghĩa thay đổi hẳn. Nguyên tắc chung giúp nhớ: V-ing thường trỏ về việc đã làm hoặc chính hành động đó, còn to-V thường trỏ tới việc sắp làm hoặc mục đích của hành động."},{"p":"Cấu trúc chính: remember doing ≠ remember to do"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I remember locking the door, but I forgot to close the window. (Nhớ việc đã làm và nhớ phải làm | Quên việc đã làm so với quên phải làm | Dừng hẳn và dừng để làm việc khác)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nhớ việc đã làm và nhớ phải làm: Remember doing là hồi tưởng; remember to do là không quên làm việc gì. (I remember meeting her. / Remember to call her.)"},{"p":"Quên việc đã làm so với quên phải làm: Forget doing thường dùng trong câu phủ định; forget to do là bỏ sót một việc. (I'll never forget seeing it. / I forgot to lock it.)"},{"p":"Dừng hẳn và dừng để làm việc khác: Stop doing là chấm dứt; stop to do là ngừng việc đang làm nhằm mục đích khác. (He stopped smoking. / He stopped to smoke.)"},{"p":"Thử làm so với cố gắng làm: Try doing là thử một cách; try to do là nỗ lực đạt một việc khó. (Try adding salt. / Try to finish by five.)"},{"p":"Ghi nhớ: Một số động từ đi được với cả V-ing và to-V nhưng nghĩa hai cách khác nhau rõ rệt."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: remember doing ≠ remember to do"},{"table":[["Động từ","Sắc thái theo dạng thức","Ví dụ"],["remember / forget","+ V-ing = việc đã xảy ra | + to-V = việc cần làm","remember posting ↔ remember to post"],["stop","+ V-ing = chấm dứt | + to-V = ngừng nhằm mục đích khác","stop reading ↔ stop to read"],["try","+ V-ing = thử xem có hiệu quả | + to-V = nỗ lực","try restarting ↔ try to restart"],["go on / mean / regret","+ V-ing = tiếp tục việc cũ, dẫn tới, tiếc về việc đã làm | + to-V = chuyển sang việc mới, có ý định, tiếc phải nói","go on talking ↔ go on to talk"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định mốc thời gian của sự việc: Việc đã xảy ra trước thì dùng V-ing; việc chưa xảy ra hoặc là mục đích thì dùng to-V. (remember locking (đã khoá) ↔ remember to lock (sắp khoá))"},{"p":"02. Đọc lại cả câu: Hai dạng đều đúng ngữ pháp nên lỗi ở nhóm này là lỗi về nghĩa, không phải lỗi hình thức. (He stopped to smoke. (ngừng việc để hút thuốc))"},{"p":"03. Nhớ nhóm dùng được cả hai dạng: Begin, start, continue dùng dạng nào cũng được, nghĩa như nhau. (It began raining / to rain.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Nhớ việc đã làm","I remember locking the door before we left.\n(Tôi nhớ là đã khoá cửa trước khi đi.)","V-ing trỏ về việc đã xảy ra trước thời điểm nhớ."],["Nhớ phải làm","Remember to lock the door when you leave.\n(Nhớ khoá cửa khi bạn ra khỏi nhà nhé.)","To-V trỏ tới việc cần làm, chưa xảy ra."],["Dừng hẳn","He stopped smoking three years ago.\n(Ba năm trước anh ấy đã bỏ thuốc.)","Stop + V-ing nghĩa là chấm dứt chính hành động đó."],["Dừng để làm việc khác","On the way home he stopped to buy some bread.\n(Trên đường về, anh ấy dừng lại mua bánh.)","Stop + to-V nghĩa là ngừng việc đang làm nhằm một mục đích khác."],["Thử một cách","The printer isn't working. Try restarting it.\n(Máy in không chạy. Bạn thử khởi động lại xem.)","Try + V-ing là thử một giải pháp để xem có hiệu quả không."],["Nỗ lực làm","I tried to finish the report, but I ran out of time.\n(Tôi đã cố làm xong báo cáo nhưng không đủ thời gian.)","Try + to-V là nỗ lực hoàn thành một việc khó."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Bốn cặp dễ nhầm nhất"},{"table":[["Cặp động từ","Đối chiếu nghĩa","Ví dụ"],["remember doing / to do","nhớ việc đã làm / nhớ phải làm","I remember paying. ↔ Remember to pay."],["stop doing / to do","bỏ hẳn / ngừng để làm việc khác","Stop talking. ↔ Stop to talk to her."],["try doing / to do","thử cách / nỗ lực","Try calling again. ↔ Try to call before six."],["regret doing / to do","tiếc việc đã làm / tiếc phải thông báo","I regret saying that. ↔ We regret to inform you…"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I remember to lock the door last night. → Đã sửa: I remember locking the door last night. — Nói về việc đã làm trong quá khứ nên dùng V-ing."},{"p":"Chưa đúng: He stopped to smoke three years ago and feels healthier. → Đã sửa: He stopped smoking three years ago and feels healthier. — Nghĩa là bỏ thuốc nên phải dùng stop + V-ing."},{"p":"Chưa đúng: I regret to tell you a lie yesterday. → Đã sửa: I regret telling you a lie yesterday. — Tiếc về việc mình đã làm thì dùng V-ing; regret to tell dùng khi sắp thông báo tin xấu."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Việc được nói tới đã xảy ra hay chưa xảy ra."},{"p":"Dạng thức được chọn truyền đạt đúng nghĩa mong muốn."},{"p":"Câu đã được đọc lại để kiểm tra nghĩa, không chỉ kiểm tra hình thức."},{"p":"Nhóm begin, start, continue không cần phân biệt dạng thức."}]}],"id":"b2-02"},{"n":3,"title":"Third conditional","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Điều kiện loại 3 nói về quá khứ đã khép lại: điều kiện không xảy ra, nên kết quả cũng không xảy ra. Cấu trúc này thường dùng để tiếc nuối, phê bình hoặc giải thích vì sao sự việc đã diễn ra như vậy. Cả hai mệnh đề đều mang dấu hiệu hoàn thành, nhưng would chỉ xuất hiện ở mệnh đề chính."},{"p":"Cấu trúc chính: If + had + V3, would have + V3"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): If I had studied harder, I would have passed the exam. (Diễn tả tiếc nuối về quá khứ | Phê bình hoặc nhận lỗi | Nguyên nhân của một kết quả đã qua)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Diễn tả tiếc nuối về quá khứ: Người nói hình dung một quá khứ khác đã không xảy ra. (If I had left earlier, I wouldn't have missed the flight.)"},{"p":"Phê bình hoặc nhận lỗi: Nêu điều lẽ ra nên làm và hệ quả đã tránh được. (If you had told me, I could have helped.)"},{"p":"Nguyên nhân của một kết quả đã qua: Hai mệnh đề cùng trỏ về cùng một quãng quá khứ. (If the road hadn't been closed, we would have arrived on time.)"},{"p":"Giảm mức chắc chắn của kết quả: Dùng might have hoặc could have thay would have. (If we had asked, they might have agreed.)"},{"p":"Ghi nhớ: Nói về điều trái với quá khứ, khi điều kiện không xảy ra nên kết quả cũng không xảy ra."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: If + had + V3, would have + V3"},{"table":[["Thành phần","Công thức","Ví dụ"],["Mệnh đề if","If + S + had (not) + V3","If she had known, …"],["Mệnh đề chính","would / could / might have + V3","… she would have come."],["Dạng rút gọn","'d have, wouldn't have, couldn't have","I'd have told you."],["Đảo ngữ trang trọng","Had + S + V3, …","Had I known, I would have called."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Đưa điều kiện vào quá khứ hoàn thành: Mệnh đề if dùng had + quá khứ phân từ và không bao giờ có would. (If I had studied…)"},{"p":"02. Đưa kết quả vào would have + V3: Could have nhấn mạnh khả năng, might have nhấn mạnh sự không chắc chắn. (I would have passed / I could have passed)"},{"p":"03. Kiểm tra cả hai mệnh đề: Nếu kết quả thuộc hiện tại thì đó là điều kiện hỗn hợp, không phải loại 3. (If I had studied, I would be a doctor now.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Tiếc nuối","If I had studied harder, I would have passed the exam.\n(Nếu tôi học chăm hơn thì tôi đã đỗ.)","Thực tế là tôi không học chăm và đã không đỗ; cả hai mệnh đề đều trái với quá khứ."],["Phê bình nhẹ","If you had told me earlier, I could have helped you.\n(Nếu bạn nói sớm hơn thì tôi đã giúp được.)","Could have nhấn mạnh khả năng giúp đỡ đã có nhưng không thành hiện thực."],["Giải thích nguyên nhân","If the road hadn't been closed, we would have arrived on time.\n(Nếu đường không bị chặn thì chúng tôi đã đến đúng giờ.)","Mệnh đề if ở dạng phủ định và dạng bị động quá khứ hoàn thành."],["Giảm mức chắc chắn","If we had asked for a discount, they might have agreed.\n(Nếu chúng ta xin giảm giá thì có lẽ họ đã đồng ý.)","Might have cho thấy người nói không chắc về kết quả giả định."],["Dạng rút gọn","I'd have come to the party if I hadn't been so tired.\n(Tôi đã đến dự tiệc nếu tôi không quá mệt.)","Would have rút gọn thành 'd have; mệnh đề if đứng sau nên không cần dấu phẩy."],["Đảo ngữ trang trọng","Had I known about the meeting, I would have rearranged my day.\n(Nếu tôi biết về cuộc họp thì tôi đã sắp xếp lại ngày làm việc.)","Bỏ if và đảo had lên trước chủ ngữ, giọng trang trọng hơn."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba loại điều kiện trên trục thời gian"},{"table":[["Loại câu","Thời gian & Tính chất","Ví dụ"],["Loại 1","tương lai, có thật khả năng","If I study, I will pass."],["Loại 2","hiện tại, giả định trái thực tế","If I studied, I would pass."],["Loại 3","quá khứ, trái với điều đã xảy ra","If I had studied, I would have passed."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: If I would have studied harder, I would have passed. → Đã sửa: If I had studied harder, I would have passed. — Mệnh đề if không dùng would."},{"p":"Chưa đúng: If I had studied harder, I would passed. → Đã sửa: If I had studied harder, I would have passed. — Mệnh đề chính cần đủ would have cộng quá khứ phân từ."},{"p":"Chưa đúng: If she had knew, she would have come. → Đã sửa: If she had known, she would have come. — Sau had phải là quá khứ phân từ known, không phải quá khứ đơn knew."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Mệnh đề if ở dạng had + quá khứ phân từ và không có would."},{"p":"Mệnh đề chính có đủ would have cộng quá khứ phân từ."},{"p":"Cả hai mệnh đề đều trỏ về quá khứ."},{"p":"Could have và might have dùng khi cần đổi sắc thái."}]}],"id":"b2-03"},{"n":4,"title":"Unless, as long as & in case","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Ngoài if, tiếng Anh còn nhiều liên từ chỉ điều kiện, mỗi liên từ mang một sắc thái riêng. Unless tương đương if … not nên mệnh đề theo sau phải ở dạng khẳng định. As long as và provided that nêu điều kiện bắt buộc phải có. In case nêu sự phòng xa cho một việc có thể xảy ra, khác hẳn if về nghĩa."},{"p":"Cấu trúc chính: unless + mệnh đề khẳng định | in case + mệnh đề hiện tại"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Take an umbrella in case it rains. (Nêu điều kiện phủ định | Nêu điều kiện bắt buộc | Phòng xa)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu điều kiện phủ định: Unless đã mang nghĩa phủ định nên mệnh đề sau nó ở dạng khẳng định. (Unless you hurry, you'll miss the bus.)"},{"p":"Nêu điều kiện bắt buộc: As long as, so long as, provided that nhấn mạnh điều kiện duy nhất cần thoả. (You can borrow it as long as you return it tomorrow.)"},{"p":"Phòng xa: In case nêu lí do chuẩn bị trước cho một việc có thể xảy ra, không phải điều kiện để hành động. (Take a map in case you get lost.)"},{"p":"Nêu điều kiện loại trừ: Even if nhấn mạnh kết quả không đổi dù điều kiện có xảy ra. (Even if it rains, we will go.)"},{"p":"Ghi nhớ: Unless mang nghĩa nếu không, as long as nêu điều kiện bắt buộc, in case nêu sự phòng xa."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: unless + mệnh đề khẳng định | in case + mệnh đề hiện tại"},{"table":[["Liên từ","Công thức / Nghĩa","Ví dụ"],["unless","unless + mệnh đề khẳng định = if … not","Unless it rains, we'll walk."],["as long as / provided that","điều kiện bắt buộc, mệnh đề ở hiện tại đơn","Provided that you pay in advance, …"],["in case","in case + hiện tại đơn (phòng xa)","Keep the receipt in case you need a refund."],["even if","kết quả không đổi dù điều kiện xảy ra","Even if she apologises, I won't forgive her."],["while (chừng nào)","mệnh đề + while + mệnh đề = chừng nào … còn (≈ as long as khi nói về khoảng kéo dài)","The data stay embargoed while the review continues."],["whether … or not","whether (+ or not) + mệnh đề = dù có … hay không","The target will be missed whether or not the subsidy continues."],["given that","given that + mệnh đề = với điều kiện là, xét rằng (≈ provided that)","The data can be shared given that they are anonymised."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chuyển if … not thành unless: Khi chuyển, phải bỏ not đi vì unless đã mang nghĩa phủ định. (If you don't hurry → Unless you hurry)"},{"p":"02. Không dùng will sau liên từ điều kiện: Quy tắc này áp dụng cho unless, as long as, in case giống như với if. (in case it rains, không phải in case it will rain)"},{"p":"03. Phân biệt in case với if: If nêu điều kiện để hành động; in case nêu lí do phòng xa trước khi biết có xảy ra hay không. (Take an umbrella if it rains. ↔ Take an umbrella in case it rains.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Phòng xa","Take an umbrella in case it rains.\n(Mang theo dù, nhỡ trời mưa.)","Người nói không biết có mưa hay không, nên mang dù là việc chuẩn bị trước."],["Điều kiện phủ định","Unless you hurry, you will miss the last bus.\n(Nếu bạn không nhanh lên thì sẽ trễ chuyến xe cuối.)","Unless đã mang nghĩa phủ định nên mệnh đề sau ở dạng khẳng định hurry."],["Điều kiện bắt buộc","You can borrow my laptop as long as you return it tomorrow.\n(Bạn mượn laptop của tôi được, miễn là mai trả.)","As long as nhấn mạnh điều kiện duy nhất cần thoả."],["Văn phong trang trọng","Provided that all documents are submitted, the application will be processed.\n(Với điều kiện toàn bộ hồ sơ được gửi, đơn sẽ được xử lí.)","Provided that trang trọng hơn as long as, thường gặp trong văn bản hành chính."],["Điều kiện loại trừ","Even if it rains tomorrow, we will go ahead with the trip.\n(Dù mai có mưa, chúng tôi vẫn đi.)","Even if nhấn mạnh kết quả không đổi, khác với if thông thường."],["Phân biệt if và in case","Call me if you have a problem, and keep this number in case your phone dies.\n(Có vấn đề thì gọi tôi và giữ số này nhỡ điện thoại bạn hết pin.)","If nêu điều kiện để gọi; in case nêu lí do giữ số từ trước."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Bốn liên từ, bốn sắc thái"},{"table":[["Liên từ","Nghĩa","Ví dụ"],["unless","nếu không","Unless you ask, nobody will help."],["as long as","miễn là, với điều kiện","As long as you're careful, it's fine."],["in case","nhỡ, để phòng","Bring cash in case the card doesn't work."],["even if","dù có","Even if you apologise, it's too late."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Take an umbrella in case it will rain. → Đã sửa: Take an umbrella in case it rains. — Sau in case không dùng will, giống như sau if."},{"p":"Chưa đúng: Unless you don't hurry, you will miss the bus. → Đã sửa: Unless you hurry, you will miss the bus. — Unless đã mang nghĩa phủ định nên không thêm not."},{"p":"Chưa đúng: I'll lend you the book as long as you will give it back. → Đã sửa: I'll lend you the book as long as you give it back. — Mệnh đề điều kiện dùng hiện tại đơn, không dùng will."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Unless đi với mệnh đề khẳng định, không có not."},{"p":"Không có will trong mệnh đề điều kiện."},{"p":"In case dùng cho sự phòng xa, không phải điều kiện hành động."},{"p":"Even if thể hiện kết quả không đổi dù điều kiện xảy ra."}]}],"id":"b2-04"},{"n":5,"title":"Clauses of concession","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Mệnh đề nhượng bộ nêu một điều lẽ ra dẫn tới kết quả khác, rồi cho thấy kết quả thực tế đi ngược lại. Người học thường nắm được nghĩa nhưng dùng sai cấu trúc, vì ba nhóm từ nhượng bộ đòi hỏi ba thành phần khác nhau: liên từ đi với mệnh đề, giới từ đi với danh từ, trạng ngữ liên kết nối hai câu."},{"p":"Cấu trúc chính: although + mệnh đề | despite + danh từ/V-ing"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Although the team trained hard, they lost the final. (Nêu nhượng bộ bằng mệnh đề | Nêu nhượng bộ bằng cụm danh từ | Nhấn mạnh mức bất ngờ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu nhượng bộ bằng mệnh đề: Although, though, even though đi với một mệnh đề có chủ ngữ và động từ. (Although it was raining, we went out.)"},{"p":"Nêu nhượng bộ bằng cụm danh từ: Despite và in spite of đi với danh từ hoặc V-ing. (Despite the rain, we went out.)"},{"p":"Nhấn mạnh mức bất ngờ: Even though mạnh hơn although; though thường đứng cuối câu trong văn nói. (Even though he apologised, she was still upset.)"},{"p":"Nối hai câu riêng: However và nevertheless nối hai câu và cần dấu chấm hoặc dấu chấm phẩy ở trước. (It was raining. However, we went out.)"},{"p":"Ghi nhớ: Although, though, even though đi với mệnh đề; despite và in spite of đi với danh từ hoặc V- ing."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: although + mệnh đề | despite + danh từ/V-ing"},{"table":[["Loại từ","Công thức","Ví dụ"],["Liên từ","although/though/even though + S + V","Although she tried, she failed."],["Giới từ","despite/in spite of + danh từ hoặc V-ing","despite trying hard"],["Giới từ với mệnh đề","despite the fact that + mệnh đề","despite the fact that she tried"],["Trạng ngữ liên kết","câu. However, câu | câu; nevertheless, câu","She tried. However, she failed."],["while","While + mệnh đề, + mệnh đề chính = tuy/trong khi (đối chiếu hai vế, đứng đầu câu)","While the method is slow, it is far more accurate."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Phân biệt mệnh đề và cụm danh từ: Có chủ ngữ và động từ thì dùng although; chỉ có danh từ thì dùng despite. (although it rained ↔ despite the rain)"},{"p":"02. Chuyển đổi giữa hai cấu trúc khi cần: Muốn dùng despite với một mệnh đề thì thêm the fact that. (despite the fact that it rained)"},{"p":"03. Đặt dấu câu đúng cho từng nhóm: Mệnh đề nhượng bộ đứng trước thì có dấu phẩy; trạng ngữ liên kết cần dấu chấm hoặc dấu chấm phẩy ở phía trước. (Although …, we went out. / We stayed in; however, …)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Mệnh đề nhượng bộ","Although the team trained hard, they lost the final.\n(Dù đội tập luyện chăm chỉ, họ vẫn thua trận chung kết.)","Although đi với một mệnh đề đầy đủ the team trained hard."],["Cụm danh từ","Despite their hard training, the team lost the final.\n(Dù tập luyện chăm chỉ, đội vẫn thua trận chung kết.)","Despite đi với cụm danh từ their hard training, không đi với mệnh đề."],["Despite với V-ing","In spite of training every day, he did not improve.\n(Dù tập mỗi ngày, anh ấy vẫn không tiến bộ.)","Sau in spite of có thể là V-ing khi chủ thể đã rõ."],["Despite the fact that","Despite the fact that he apologised, she was still upset.\n(Dù anh ấy đã xin lỗi, cô ấy vẫn giận.)","Thêm the fact that cho phép despite đi với một mệnh đề."],["Though ở cuối câu","The hotel was expensive. It was comfortable, though.\n(Khách sạn đắt. Nhưng cũng thoải mái.)","Though đứng cuối câu là cách nói rất thông dụng trong hội thoại."],["Trạng ngữ liên kết","The evidence was limited; nevertheless, the committee approved the plan.\n(Bằng chứng còn hạn chế; tuy vậy hội đồng vẫn thông qua kế hoạch.)","Nevertheless nối hai câu và cần dấu chấm phẩy ở trước, dấu phẩy ở sau."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba nhóm từ nhượng bộ"},{"table":[["Từ / Cụm từ","Loại từ & Cách dùng","Ví dụ"],["although / even though","liên từ, đi với mệnh đề","Although he tried, he failed."],["despite / in spite of","giới từ, đi với danh từ hoặc V-ing","Despite his effort, he failed."],["however / nevertheless","trạng ngữ liên kết, nối hai câu","He tried. However, he failed."],["though ở cuối câu","văn nói, mang sắc thái nhẹ","He failed. He tried hard, though."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Although the hard training, they lost the final. → Đã sửa: Although they trained hard, they lost the final. — Although đòi hỏi một mệnh đề có chủ ngữ và động từ."},{"p":"Chưa đúng: Despite it was raining, we went out. → Đã sửa: Despite the rain, we went out. — Despite đi với danh từ; nếu muốn dùng mệnh đề thì viết despite the fact that."},{"p":"Chưa đúng: Although it was raining, but we went out. → Đã sửa: Although it was raining, we went out. — Một quan hệ chỉ dùng một liên từ, không dùng đồng thời although và but."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Thành phần nhượng bộ là mệnh đề hay cụm danh từ."},{"p":"Despite và in spite of không đi trực tiếp với mệnh đề."},{"p":"Không dùng đồng thời although và but trong một câu."},{"p":"Dấu câu quanh trạng ngữ liên kết đã đúng."}]}],"id":"b2-05"},{"n":6,"title":"Wish & if only","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Wish và if only diễn tả điều người nói mong khác đi so với thực tế. Dạng động từ sau wish lùi một bậc so với thời điểm được nói tới: muốn hiện tại khác đi thì dùng quá khứ đơn, muốn quá khứ khác đi thì dùng quá khứ hoàn thành, muốn người khác đổi hành vi thì dùng would. If only mang nghĩa như wish nhưng nhấn mạnh hơn."},{"p":"Cấu trúc chính: wish + quá khứ đơn | wish + had + V3"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I wish I knew the answer. (Mong hiện tại khác đi | Tiếc về quá khứ | Mong người khác thay đổi hành vi)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Mong hiện tại khác đi: Dùng quá khứ đơn sau wish, với be thì dùng were cho mọi chủ ngữ. (I wish I had more free time.)"},{"p":"Tiếc về quá khứ: Dùng had + quá khứ phân từ để nói về điều đã không xảy ra như mong muốn. (I wish I had studied medicine.)"},{"p":"Mong người khác thay đổi hành vi: Wish + would thường mang sắc thái phàn nàn. (I wish you would stop interrupting.)"},{"p":"Nhấn mạnh sự tiếc nuối: If only thay cho wish khi muốn nhấn giọng hơn. (If only I hadn't said that.)"},{"p":"Ghi nhớ: Wish + quá khứ đơn cho hiện tại, wish + had + V3 cho quá khứ, wish + would cho mong muốn thay đổi."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: wish + quá khứ đơn | wish + had + V3"},{"table":[["Trường hợp","Công thức","Ví dụ"],["Hiện tại","wish + S + quá khứ đơn","I wish I spoke Japanese."],["Quá khứ","wish + S + had + V3","I wish I had taken that job."],["Hành vi của người khác","wish + S + would + V","I wish he would listen."],["Khả năng","wish + S + could + V","I wish I could help."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định mốc của điều mong muốn: Hiện tại thì lùi về quá khứ đơn; quá khứ thì lùi về quá khứ hoàn thành. (I wish I knew ↔ I wish I had known)"},{"p":"02. Dùng were trong cấu trúc giả định: Dạng were là chuẩn mực trong văn viết. (I wish I were taller.)"},{"p":"03. Chọn would hay could theo nội dung: Would dùng khi mong người khác đổi hành vi; could dùng khi mong về khả năng. (I wish you would help. ↔ I wish I could help.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Mong hiện tại khác đi","I wish I knew the answer to this question.\n(Tôi ước mình biết đáp án câu này.)","Thực tế là tôi không biết; quá khứ đơn knew đánh dấu tính giả định, không chỉ thời gian."],["Dùng were","She wishes she were taller.\n(Cô ấy mong mình cao hơn.)","Trong cấu trúc giả định, were dùng cho mọi chủ ngữ."],["Tiếc về quá khứ","I wish I had studied medicine instead of law.\n(Tôi tiếc là đã không học y mà lại học luật.)","Quá khứ hoàn thành cho biết điều mong muốn thuộc về quá khứ đã khép lại."],["Phàn nàn về hành vi","I wish you would stop interrupting me.\n(Tôi mong bạn đừng chen ngang nữa.)","Wish + would nhằm vào hành vi của người khác, mang sắc thái phàn nàn."],["Mong về khả năng","I wish I could come to your wedding, but I'll be abroad.\n(Tôi mong có thể dự cưới bạn nhưng lúc đó tôi ở nước ngoài.)","Could dùng khi điều mong muốn liên quan đến khả năng thực hiện."],["If only","If only I hadn't said that to her.\n(Giá mà tôi đã không nói câu đó với cô ấy.)","If only nhấn mạnh sự tiếc nuối hơn wish, cấu trúc theo sau giống hệt."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba dạng sau wish"},{"table":[["Cấu trúc","Nghĩa","Ví dụ"],["wish + quá khứ đơn","mong hiện tại khác đi","I wish I lived nearer."],["wish + had + V3","tiếc về quá khứ","I wish I had left earlier."],["wish + would","mong người khác đổi hành vi","I wish they would be quiet."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I wish I know the answer. → Đã sửa: I wish I knew the answer. — Sau wish, điều mong muốn ở hiện tại dùng quá khứ đơn."},{"p":"Chưa đúng: I wish I would have studied medicine. → Đã sửa: I wish I had studied medicine. — Tiếc về quá khứ dùng had + quá khứ phân từ, không dùng would have."},{"p":"Chưa đúng: I wish you will stop interrupting. → Đã sửa: I wish you would stop interrupting. — Sau wish dùng would chứ không dùng will."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Điều mong muốn thuộc hiện tại hay quá khứ."},{"p":"Dạng động từ đã lùi một bậc so với thời điểm đó."},{"p":"Động từ be ở dạng were trong cấu trúc giả định."},{"p":"Sau wish không dùng will."}]}],"id":"b2-06"},{"n":7,"title":"Have / get something done","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Cấu trúc nhờ người khác làm cho biết chủ ngữ là người sắp xếp hoặc chi trả, còn người thực hiện thực tế là ai thì thường không cần nêu. Trật tự bắt buộc là have hoặc get, rồi tân ngữ, rồi quá khứ phân từ. Đặt quá khứ phân từ trước tân ngữ sẽ làm câu đổi nghĩa hoàn toàn."},{"p":"Cấu trúc chính: have/get + tân ngữ + V3"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I had my car repaired yesterday. (Thuê dịch vụ | Nhờ vả trong giao tiếp hằng ngày | Nói về việc không may xảy đến)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Thuê dịch vụ: Người nói trả tiền để người khác làm việc đó. (We had the house painted.)"},{"p":"Nhờ vả trong giao tiếp hằng ngày: Get thường nghe tự nhiên và thân mật hơn have. (I must get my hair cut.)"},{"p":"Nói về việc không may xảy đến: Cấu trúc này cũng dùng khi chủ ngữ là người chịu tác động ngoài ý muốn. (He had his wallet stolen.)"},{"p":"Nhờ một người cụ thể thực hiện: Dùng have + người + động từ nguyên mẫu hoặc get + người + to-V. (I had the plumber check the pipes.)"},{"p":"Ghi nhớ: Diễn tả việc chủ ngữ thuê hoặc nhờ người khác thực hiện, không tự mình làm."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: have/get + tân ngữ + V3"},{"table":[["Dạng thức","Công thức","Ví dụ"],["Cấu trúc cơ bản","S + have/get + tân ngữ + V3","She got her phone fixed."],["Các thì khác nhau","have chia theo thì, phần còn lại giữ nguyên","I will have it delivered. / I have had it cleaned."],["Nhờ người cụ thể","have + người + V nguyên mẫu | get + người + to-V","I had Nam move the table. / I got Nam to move the table."],["Nghi vấn và phủ định","dùng trợ động từ như với have thông thường","Did you have the car serviced?"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Phân biệt người sắp xếp và người thực hiện: Chủ ngữ là người sắp xếp; người thực hiện thường không nêu. (I had my car repaired. (thợ sửa, không phải tôi))"},{"p":"02. Giữ tân ngữ trước quá khứ phân từ: Đảo lại sẽ thành thì hoàn thành với nghĩa tự mình làm. (had my car repaired ↔ had repaired my car)"},{"p":"03. Chia have hoặc get theo thì cần dùng: Chỉ phần have hoặc get biến đổi, tân ngữ và quá khứ phân từ giữ nguyên. (I am having it repainted.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Thuê dịch vụ","I had my car repaired yesterday.\n(Hôm qua tôi đem xe đi sửa.)","Tôi không tự sửa; trật tự tân ngữ my car trước quá khứ phân từ repaired là bắt buộc."],["Dùng get","I must get my hair cut before the interview.\n(Tôi phải đi cắt tóc trước buổi phỏng vấn.)","Get nghe tự nhiên và thân mật hơn have trong hội thoại."],["Việc không may","He had his wallet stolen on the bus.\n(Anh ấy bị mất ví trên xe buýt.)","Ở đây chủ ngữ là người chịu tác động ngoài ý muốn, không phải người sắp xếp."],["Nhờ người cụ thể","We had the plumber check all the pipes.\n(Chúng tôi nhờ thợ nước kiểm tra toàn bộ đường ống.)","Have + người + động từ nguyên mẫu khi muốn nêu rõ người thực hiện."],["Dùng get với to-V","I got my brother to help me move the furniture.\n(Tôi nhờ anh trai giúp dọn đồ.)","Get + người + to-V là mẫu tương ứng của have + người + V nguyên mẫu."],["Ở thì tương lai","We will have the documents translated by Friday.\n(Chúng tôi sẽ cho dịch tài liệu trước thứ Sáu.)","Chỉ phần have đổi theo thì, tân ngữ và quá khứ phân từ giữ nguyên."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba cấu trúc gần hình thức"},{"table":[["Cấu trúc","Nghĩa","Ví dụ"],["have + O + V3","nhờ hoặc thuê người khác làm","I had the room cleaned."],["have + V3","thì hoàn thành, tự mình làm","I have cleaned the room."],["have + người + V nguyên mẫu","nhờ một người cụ thể","I had Minh clean the room."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I had repaired my car yesterday. → Đã sửa: I had my car repaired yesterday. — Đảo trật tự sẽ thành quá khứ hoàn thành với nghĩa tôi tự sửa xe."},{"p":"Chưa đúng: I must get cut my hair. → Đã sửa: I must get my hair cut. — Tân ngữ phải đứng trước quá khứ phân từ."},{"p":"Chưa đúng: We had the plumber to check the pipes. → Đã sửa: We had the plumber check the pipes. — Have + người đi với động từ nguyên mẫu không to; chỉ get mới dùng to-V."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Tân ngữ đứng trước quá khứ phân từ."},{"p":"Have hoặc get đã chia đúng theo thì."},{"p":"Có cần nêu người thực hiện hay không."},{"p":"Have + người đi với động từ nguyên mẫu, get + người đi với to-V."}]}],"id":"b2-07"},{"n":8,"title":"Advanced passive forms","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Ở trình độ B2, câu bị động không chỉ còn là đổi chỗ chủ ngữ và tân ngữ. Động từ có hai tân ngữ cho phép tạo hai câu bị động khác nhau, và người viết chọn câu nào tuỳ theo thành phần muốn nhấn. Ngoài ra, bị động còn có dạng nguyên mẫu to be cộng quá khứ phân từ dùng sau động từ khuyết thiếu và sau một số động từ, cùng dạng being cộng quá khứ phân từ dùng sau giới từ."},{"p":"Cấu trúc chính: S + be + V3 + tân ngữ còn lại | to be + V3 | being + V3"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She was given a prize, and the prize was given to her. (Động từ có hai tân ngữ | Sau động từ khuyết thiếu | Sau giới từ và động từ đi với V-ing)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Động từ có hai tân ngữ: Give, send, offer, tell, show cho hai câu bị động; dạng đưa người lên làm chủ ngữ thông dụng hơn. (He was offered a job. / A job was offered to him.)"},{"p":"Sau động từ khuyết thiếu: Dùng to be cộng quá khứ phân từ sau các động từ như need, want, have to. (This form needs to be signed.)"},{"p":"Sau giới từ và động từ đi với V-ing: Dùng being cộng quá khứ phân từ. (She hates being interrupted.)"},{"p":"Dạng hoàn thành của bị động: Having been cộng quá khứ phân từ dùng khi việc đã xong trước đó. (Having been warned, they left early.)"},{"p":"Ghi nhớ: Động từ có hai tân ngữ cho hai câu bị động; sau động từ khuyết thiếu và giới từ cũng có dạng bị động riêng."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + be + V3 + tân ngữ còn lại | to be + V3 | being + V3"},{"table":[["Dạng thức","Công thức","Ví dụ"],["Hai tân ngữ","người + be + V3 + vật | vật + be + V3 + to/for + người","I was sent an email. / An email was sent to me."],["Nguyên mẫu bị động","to be + V3","The report needs to be revised."],["Danh động từ bị động","being + V3","He remembers being told about it."],["Hoàn thành bị động","having been + V3","Having been rejected twice, she applied again."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định động từ có mấy tân ngữ: Nếu có hai, chọn tân ngữ muốn nhấn để làm chủ ngữ mới. (They gave Mai a prize. → Mai was given a prize.)"},{"p":"02. Giữ giới từ khi vật làm chủ ngữ: Tân ngữ chỉ người lúc này cần to hoặc for ở phía trước. (A prize was given to Mai.)"},{"p":"03. Chọn dạng bị động theo thành phần đứng trước: Sau động từ khuyết thiếu dùng to be cộng V3; sau giới từ dùng being cộng V3. (must be done / without being seen)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Hai câu bị động","She was given a prize, and the prize was given to her at the ceremony.\n(Cô ấy được trao giải và giải thưởng được trao cho cô ấy trong buổi lễ.)","Cùng một câu chủ động cho hai câu bị động; khi vật lên làm chủ ngữ thì người nhận cần giới từ to."],["Nhấn người nhận","He was offered a job in Da Nang last month.\n(Tháng trước anh ấy được mời làm việc ở Đà Nẵng.)","Đưa người lên làm chủ ngữ là cách thông dụng hơn với động từ offer."],["Nguyên mẫu bị động","This form needs to be signed by both parents.\n(Mẫu đơn này cần được cả bố và mẹ kí.)","Sau need là to be cộng quá khứ phân từ."],["Danh động từ bị động","She hates being interrupted while she is working.\n(Cô ấy rất ghét bị ngắt lời khi đang làm việc.)","Hate đi với V-ing nên dạng bị động là being cộng quá khứ phân từ."],["Sau giới từ","He left without being noticed.\n(Anh ấy rời đi mà không ai để ý.)","Sau giới từ without phải là being cộng quá khứ phân từ."],["Hoàn thành bị động","Having been warned about the storm, the crew stayed in port.\n(Sau khi được cảnh báo về cơn bão, thuỷ thủ đoàn ở lại cảng.)","Having been cộng quá khứ phân từ diễn tả việc xảy ra trước và mang nghĩa bị động."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Các dạng bị động theo vị trí trong câu"},{"table":[["Dạng bị động","Vị trí & Cách dùng","Ví dụ"],["be + V3","bị động thường, chia theo thì","The door was locked."],["to be + V3","sau động từ khuyết thiếu và động từ đi với to-V","It must be locked."],["being + V3","sau giới từ và động từ đi với V-ing","I hate being watched."],["having been + V3","bị động xảy ra trước","Having been locked, the door stayed shut."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: A prize was given her by the committee. → Đã sửa: A prize was given to her by the committee. — Khi vật lên làm chủ ngữ, người nhận cần giới từ to ở phía trước."},{"p":"Chưa đúng: This form needs to be sign by both parents. → Đã sửa: This form needs to be signed by both parents. — Sau to be phải là quá khứ phân từ."},{"p":"Chưa đúng: She hates to be interrupting while working. → Đã sửa: She hates being interrupted while working. — Hate đi với V-ing và dạng bị động của V-ing là being cộng quá khứ phân từ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Động từ có một hay hai tân ngữ."},{"p":"Giới từ to hoặc for được thêm khi vật lên làm chủ ngữ."},{"p":"Dạng bị động phù hợp với thành phần đứng trước."},{"p":"Động từ chính luôn ở dạng quá khứ phân từ."}]}],"id":"b2-08"},{"n":9,"title":"Reported statements","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Câu tường thuật truyền đạt lời của người khác theo góc nhìn của người kể. Khi thời điểm nói thay đổi, ba thành phần thường được điều chỉnh: thì của động từ lùi một bậc, đại từ đổi theo người được nhắc đến, còn trạng từ chỉ thời gian và nơi chốn đổi theo mốc mới. Nếu nội dung vẫn đúng ở hiện tại, người nói có thể giữ nguyên thì."},{"p":"Cấu trúc chính: said (that) + mệnh đề đã lùi thì"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She said she was tired. (Thuật lại lời kể | Thuật lại trong báo cáo và tin tức | Giữ nguyên thì khi nội dung vẫn đúng)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Thuật lại lời kể: Say dùng khi không nêu người nghe; tell cần một tân ngữ chỉ người nghe. (She said she was busy. / She told me she was busy.)"},{"p":"Thuật lại trong báo cáo và tin tức: Dùng để dẫn lại thông tin từ nguồn khác. (The report said that prices had risen.)"},{"p":"Giữ nguyên thì khi nội dung vẫn đúng: Sự thật hiển nhiên hoặc tình trạng còn hiệu lực không cần lùi thì. (He said that water boils at 100°C.)"},{"p":"Thuật lại trong hội thoại: Liên từ that thường được lược bỏ trong văn nói. (She said she would call later.)"},{"p":"Ghi nhớ: Khi tường thuật, thì lùi một bậc và đại từ cùng trạng từ thời gian được điều chỉnh."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: said (that) + mệnh đề đã lùi thì"},{"table":[["Thành phần đổi","Quy tắc biến đổi","Ví dụ"],["Lùi thì","hiện tại đơn → quá khứ đơn | hiện tại tiếp diễn → quá khứ tiếp diễn","“I am tired.” → She said she was tired."],["Lùi thì hoàn thành","quá khứ đơn và hiện tại hoàn thành → quá khứ hoàn thành","“I saw it.” → He said he had seen it."],["Động từ khuyết thiếu","will → would | can → could | may → might | must → had to","“I will call.” → She said she would call."],["Đổi trạng từ","today → that day | tomorrow → the next day | here → there | now → then","“I'll come tomorrow.” → He said he would come the next day."],["Lùi thì với động từ bất quy tắc","went → had gone | saw → had seen | did → had done","“I went to Hue.” → She said she had gone to Hue."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Lùi thì của động từ một bậc: Quá khứ hoàn thành là bậc cuối nên không lùi thêm được. (is → was /has done → had done)"},{"p":"02. Đổi đại từ theo người tường thuật: Ngôi thứ nhất trong lời gốc thường đổi thành ngôi thứ ba. (“I am ready.” → He said he was ready.)"},{"p":"03. Đổi trạng từ chỉ thời gian và nơi chốn: Chỉ đổi khi mốc thời gian hoặc nơi chốn của lời tường thuật đã khác lời gốc. (yesterday → the day before)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Lùi thì hiện tại đơn","“I am tired.” → She said she was tired.\n(“Tôi mệt.” → Cô ấy nói cô ấy mệt.)","Am lùi thành was và đại từ I đổi thành she."],["Lùi thì quá khứ đơn","“I saw the film.” → He said he had seen the film.\n(“Tôi đã xem phim đó.” → Anh ấy nói anh ấy đã xem bộ phim đó.)","Quá khứ đơn lùi thành quá khứ hoàn thành."],["Động từ khuyết thiếu","“I will call you tomorrow.” → She said she would call me the next day.\n(“Mai tôi sẽ gọi cho bạn.” → Cô ấy nói hôm sau sẽ gọi cho tôi.)","Will lùi thành would; tomorrow đổi thành the next day; you đổi thành me."],["Dùng tell","She told me she had already finished the report.\n(Cô ấy nói với tôi là đã làm xong báo cáo.)","Tell cần một tân ngữ chỉ người nghe, còn say thì không."],["Không lùi thì","The teacher said that water boils at one hundred degrees.\n(Thầy nói nước sôi ở một trăm độ.)","Sự thật hiển nhiên vẫn đúng nên không cần lùi thì."],["Lược bỏ that","He said he was going to apply for the job.\n(Anh ấy nói sẽ xin việc đó.)","Liên từ that thường được lược bỏ trong văn nói."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Say và tell"},{"table":[["Cấu trúc","Quy tắc","Ví dụ"],["say + (that) + mệnh đề","không nêu người nghe","She said she was late."],["tell + người + (that) + mệnh đề","bắt buộc nêu người nghe","She told me she was late."],["say to + người","dạng ít dùng hơn nhưng đúng","She said to me that she was late."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She said she is tired. → Đã sửa: She said she was tired. — Động từ trong lời tường thuật phải lùi một bậc so với lời gốc."},{"p":"Chưa đúng: She said me she was busy. → Đã sửa: She told me she was busy. — Say không đi với tân ngữ chỉ người nghe; dùng tell hoặc say to me."},{"p":"Chưa đúng: He said he will call tomorrow. → Đã sửa: He said he would call the next day. — Will lùi thành would và tomorrow đổi theo mốc tường thuật."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Thì của động từ đã lùi một bậc."},{"p":"Đại từ đã đổi theo người tường thuật."},{"p":"Trạng từ thời gian và nơi chốn đã điều chỉnh khi cần."},{"p":"Say và tell dùng đúng về tân ngữ chỉ người nghe."}]}],"id":"b2-09"},{"n":10,"title":"Reported questions & commands","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Khi tường thuật một câu hỏi, câu đó không còn là câu hỏi nữa nên phải trở về trật tự chủ ngữ trước động từ, bỏ trợ động từ do và bỏ dấu hỏi. Câu hỏi có từ hỏi thì giữ nguyên từ hỏi; câu hỏi có hoặc không thì dùng if hoặc whether. Câu mệnh lệnh chuyển thành tell hoặc ask cộng tân ngữ cộng động từ nguyên mẫu có to."},{"p":"Cấu trúc chính: asked + wh-/if + S + V | told + O + to-V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She asked where I lived. (Tường thuật câu hỏi có từ hỏi | Tường thuật câu hỏi có hoặc không | Tường thuật lời yêu cầu và mệnh lệnh)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Tường thuật câu hỏi có từ hỏi: Giữ từ hỏi rồi viết tiếp theo trật tự câu kể. (He asked what my name was.)"},{"p":"Tường thuật câu hỏi có hoặc không: Dùng if hoặc whether để nối. (She asked if I was ready.)"},{"p":"Tường thuật lời yêu cầu và mệnh lệnh: Tell mang sắc thái ra lệnh, ask mang sắc thái nhờ vả. (He told me to wait. / He asked me to help.)"},{"p":"Tường thuật lời ngăn cản: Dạng phủ định là not to + động từ nguyên mẫu. (She told us not to be late.)"},{"p":"Ghi nhớ: Câu hỏi tường thuật trở về trật tự câu kể; câu mệnh lệnh chuyển thành tell hoặc ask + O + to- V."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: asked + wh-/if + S + V | told + O + to-V"},{"table":[["Dạng câu gốc","Công thức tường thuật","Ví dụ"],["Câu hỏi có từ hỏi","asked + wh- + S + V (đã lùi thì)","She asked where I lived."],["Câu hỏi có hoặc không","asked + if/whether + S + V","He asked if I had finished."],["Mệnh lệnh","told/asked + O + to-V","She told me to sit down."],["Mệnh lệnh phủ định","told/asked + O + not to-V","He asked me not to tell anyone."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Đưa câu hỏi về trật tự câu kể: Chủ ngữ đứng trước động từ, bỏ trợ động từ do, does, did và bỏ dấu hỏi. (“Where do you live?” → where I lived)"},{"p":"02. Chọn từ nối phù hợp: Có từ hỏi thì giữ từ hỏi; không có thì dùng if hoặc whether. (if I was ready)"},{"p":"03. Chuyển mệnh lệnh thành to-V: Thêm tân ngữ chỉ người nhận lệnh, rồi động từ nguyên mẫu có to. (“Wait here.” → He told me to wait there.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Câu hỏi có từ hỏi","“Where do you live?” → She asked where I lived.\n(“Bạn sống ở đâu?” → Cô ấy hỏi tôi sống ở đâu.)","Bỏ trợ động từ do, đưa chủ ngữ I lên trước động từ và lùi thì thành lived."],["Câu hỏi có hoặc không","“Are you ready?” → He asked if I was ready.\n(“Bạn xong chưa?” → Anh ấy hỏi tôi đã xong chưa.)","Không có từ hỏi nên dùng if; trật tự trở về chủ ngữ trước động từ."],["Dùng whether","She asked whether the shop was still open.\n(Cô ấy hỏi cửa hàng còn mở không.)","Whether trang trọng hơn if và bắt buộc khi có cụm or not đứng ngay sau."],["Mệnh lệnh","“Sit down, please.” → She told me to sit down.\n(“Mời ngồi.” → Cô ấy bảo tôi ngồi xuống.)","Tell cộng tân ngữ cộng to-V; cấu trúc này không lùi thì."],["Lời nhờ vả","“Could you help me?” → He asked me to help him.\n(“Bạn giúp tôi được không?” → Anh ấy nhờ tôi giúp.)","Lời nhờ vả dùng ask, khác với tell mang sắc thái ra lệnh."],["Mệnh lệnh phủ định","“Don't be late.” → The teacher told us not to be late.\n(“Đừng đến muộn.” → Thầy nhắc chúng tôi đừng đến muộn.)","Dạng phủ định là not to cộng động từ nguyên mẫu."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba kiểu lời nói khi tường thuật"},{"table":[["Kiểu lời nói","Cấu trúc tường thuật","Ví dụ"],["câu kể","said / told + mệnh đề","He said he was busy."],["câu hỏi","asked + wh-/if + mệnh đề","He asked if I was busy."],["mệnh lệnh","told / asked + O + to-V","He told me to hurry."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She asked where did I live. → Đã sửa: She asked where I lived. — Câu hỏi tường thuật trở về trật tự câu kể và bỏ trợ động từ did."},{"p":"Chưa đúng: He asked that if I was ready. → Đã sửa: He asked if I was ready. — Không dùng that cùng với if trong câu hỏi tường thuật."},{"p":"Chưa đúng: She told to me to sit down. → Đã sửa: She told me to sit down. — Tell đi trực tiếp với tân ngữ chỉ người, không cần giới từ to."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Câu hỏi đã trở về trật tự chủ ngữ trước động từ."},{"p":"Trợ động từ do, does, did đã được bỏ."},{"p":"Từ nối là từ hỏi, if hoặc whether cho đúng loại câu hỏi."},{"p":"Mệnh lệnh chuyển thành tell hoặc ask cộng tân ngữ cộng to-V."},{"p":"Lùi thì không bắt buộc khi điều được hỏi đến nay vẫn đúng: giữ has cũng được chấp nhận."},{"p":"Trợ động từ will lùi thành would khi thuật lại."}]}],"id":"b2-10"},{"n":11,"title":"Reporting verbs","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Người viết thành thạo chọn động từ tường thuật thể hiện đúng hành vi ngôn ngữ: khuyên, đề nghị, thừa nhận, từ chối, cảnh báo, giải thích. Say và tell chỉ là hai lựa chọn trung tính nhất trong nhóm này. Mỗi động từ chi phối một mẫu câu riêng, và việc nhớ sai mẫu là lỗi phổ biến hơn cả việc chọn sai động từ."},{"p":"Cấu trúc chính: advise + O + to-V | suggest + V-ing"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She suggested taking a taxi and advised me to leave early. (Tường thuật lời khuyên và lời yêu cầu | Tường thuật lời đề nghị | Tường thuật lời thừa nhận và phủ nhận)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Tường thuật lời khuyên và lời yêu cầu: Advise, warn, remind, encourage, persuade đi với tân ngữ rồi to- V. (He reminded me to bring my passport.)"},{"p":"Tường thuật lời đề nghị: Suggest và recommend đi với V-ing hoặc mệnh đề that, không đi với tân ngữ rồi to-V. (She suggested booking early.)"},{"p":"Tường thuật lời thừa nhận và phủ nhận: Admit và deny đi với V-ing hoặc mệnh đề that. (He admitted breaking the window.)"},{"p":"Tường thuật lời hứa và lời từ chối: Promise, refuse, offer, agree, threaten đi với to-V mà không cần tân ngữ. (She refused to answer.)"},{"p":"Ghi nhớ: Mỗi động từ tường thuật đòi hỏi một mẫu câu riêng: advise + O + to-V, suggest + V-ing, admit + V-ing."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: advise + O + to-V | suggest + V-ing"},{"table":[["Mẫu cấu trúc","Nhóm động từ","Ví dụ"],["+ O + to-V","advise, warn, remind, encourage, persuade, invite, order","They invited us to join them."],["+ to-V","promise, refuse, offer, agree, threaten, claim","He offered to drive us home."],["+ V-ing","suggest, recommend, admit, deny, mention, apologise for","He denied taking the money."],["+ mệnh đề that","explain, insist, complain, point out, suggest, admit","She explained that the file was corrupted."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định hành vi ngôn ngữ của lời gốc: Lời đó là khuyên, đề nghị, thừa nhận, từ chối hay cảnh báo. (“You should rest.” → advise)"},{"p":"02. Nhớ mẫu câu của động từ đã chọn: Nhóm advise cần tân ngữ; nhóm suggest không nhận tân ngữ rồi to-V. (advised me to rest / suggested resting)"},{"p":"03. Kiểm tra giới từ nếu động từ đòi hỏi: Apologise for, accuse of, blame for, congratulate on đều cần giới từ rồi V-ing. (She apologised for being late.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Nhóm cần tân ngữ","The doctor advised me to rest for a week.\n(Bác sĩ khuyên tôi nghỉ một tuần.)","Advise cần một tân ngữ chỉ người nhận lời khuyên rồi mới đến to-V."],["Nhóm đi với V-ing","She suggested taking a taxi instead of waiting.\n(Cô ấy đề nghị bắt taxi thay vì đứng đợi.)","Suggest không nhận tân ngữ rồi to-V; nó đi với V-ing hoặc mệnh đề that."],["Thừa nhận","He admitted breaking the window.\n(Cậu ấy thừa nhận đã làm vỡ cửa sổ.)","Admit đi với V-ing; cũng viết được là admitted that he had broken the window."],["Từ chối","The manager refused to discuss the matter.\n(Người quản lí từ chối bàn về việc đó.)","Refuse đi với to-V và không cần tân ngữ."],["Cảnh báo","They warned us not to swim beyond the buoys.\n(Họ cảnh báo chúng tôi không được bơi ra ngoài phao.)","Warn cần tân ngữ và dạng phủ định là not to cộng nguyên mẫu."],["Có giới từ","She apologised for arriving so late.\n(Cô ấy xin lỗi vì đến muộn.)","Apologise đòi hỏi giới từ for và sau giới từ là V-ing."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba nhóm mẫu câu dễ nhầm"},{"table":[["Mẫu câu","Đặc điểm","Ví dụ"],["advise / warn / remind + O + to-V","có tân ngữ","He reminded her to sign it."],["suggest / recommend + V-ing","không có tân ngữ","He suggested signing it."],["promise / refuse / offer + to-V","không cần tân ngữ","He promised to sign it."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She suggested me to take a taxi. → Đã sửa: She suggested taking a taxi. — Suggest không đi với tân ngữ rồi to-V."},{"p":"Chưa đúng: He admitted to break the window. → Đã sửa: He admitted breaking the window. — Admit đi với V-ing."},{"p":"Chưa đúng: The doctor advised to rest for a week. → Đã sửa: The doctor advised me to rest for a week. — Advise cần một tân ngữ chỉ người nhận lời khuyên."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Động từ tường thuật phản ánh đúng hành vi ngôn ngữ."},{"p":"Mẫu câu đi kèm đúng với động từ đã chọn."},{"p":"Tân ngữ có hoặc không theo yêu cầu của động từ."},{"p":"Giới từ bắt buộc đã được dùng cùng V-ing."}]}],"id":"b2-11"},{"n":12,"title":"Non-defining relative clauses","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Mệnh đề quan hệ không xác định thêm thông tin phụ về một đối tượng đã được xác định rõ. Vì thông tin là phụ, mệnh đề được tách bằng dấu phẩy, không dùng that và không được lược bỏ đại từ quan hệ. Loại mệnh đề này cũng dùng which để bình luận về cả mệnh đề đứng trước."},{"p":"Cấu trúc chính: danh từ, who/which/whose …, …"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): My brother, who lives in Hue, is a teacher. (Thông tin thêm về đối tượng đã xác định | Bình luận về cả mệnh đề trước | Nêu quan hệ sở hữu bổ sung)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Thông tin thêm về đối tượng đã xác định: Đối tượng thường là tên riêng hoặc danh từ đã rõ nhờ ngữ cảnh. (Hue, which is my hometown, is very peaceful.)"},{"p":"Bình luận về cả mệnh đề trước: Which đứng sau dấu phẩy và trỏ về toàn bộ ý vừa nêu. (He arrived late, which annoyed everyone.)"},{"p":"Nêu quan hệ sở hữu bổ sung: Whose dùng cho cả người và vật trong mệnh đề không xác định. (Mai, whose father is a doctor, wants to study medicine.)"},{"p":"Nêu một phần của tập hợp: Dùng cấu trúc some of whom, many of which sau dấu phẩy. (The students, most of whom were beginners, did very well.)"},{"p":"Ghi nhớ: Nêu thông tin bổ sung, luôn tách bằng dấu phẩy và không dùng that."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: danh từ, who/which/whose …, …"},{"table":[["Đối tượng / Chức năng","Công thức","Ví dụ"],["Người",", who …, | , whom … (vị trí tân ngữ)","Mr Nam, who teaches physics, retired last year."],["Vật",", which …,","The museum, which opened in 1990, is free."],["Bình luận cả mệnh đề","mệnh đề, which + bình luận","She passed the exam, which surprised nobody."],["Nêu một phần",", some/most/many of whom/which,","the files, many of which were missing,"],["when · where","mốc thời gian + when + mệnh đề (= in which) | nơi chốn/tổ chức + where + mệnh đề","In 2020, when the pandemic began…/ The station, where readings began in 1894, closed last year."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xét mức xác định của đối tượng: Nếu người đọc đã biết chính xác là ai hoặc cái gì thì mệnh đề là không xác định. (My brother, who lives in Hue, …)"},{"p":"02. Tách mệnh đề bằng hai dấu phẩy: Nếu mệnh đề nằm giữa câu thì cần hai dấu phẩy. (Hue, which I love, is quiet.)"},{"p":"03. Giữ đại từ quan hệ và tránh that: Hai điểm này là khác biệt hình thức quan trọng nhất so với mệnh đề xác định. (The book, which I bought yesterday, is excellent.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Bổ nghĩa cho người","My brother, who lives in Hue, is a teacher.\n(Anh trai tôi, người sống ở Huế, là giáo viên.)","Tôi chỉ có một anh trai nên thông tin về nơi sống là phụ, tách bằng hai dấu phẩy."],["Bổ nghĩa cho vật","The museum, which opened in 1990, is free on Sundays.\n(Viện bảo tàng, mở năm 1990, miễn phí vào Chủ nhật.)","Which không thay được bằng that trong mệnh đề không xác định."],["Bình luận cả mệnh đề","He arrived two hours late, which annoyed everyone.\n(Anh ấy đến muộn hai tiếng, điều đó làm mọi người khó chịu.)","Which ở đây trỏ về toàn bộ việc đến muộn, không trỏ về một danh từ riêng lẻ."],["Quan hệ sở hữu","Mai, whose father is a doctor, wants to study medicine.\n(Mai, bố là bác sĩ, muốn học y.)","Whose đi kèm một danh từ ngay sau và dùng được trong cả hai loại mệnh đề quan hệ."],["Nêu một phần của tập hợp","The students, most of whom were beginners, made good progress.\n(Các học viên, phần lớn là người mới bắt đầu, tiến bộ tốt.)","Sau giới từ of thì dùng whom cho người và which cho vật."],["Vị trí tân ngữ","Mr Nam, whom we met at the conference, has written three books.\n(Ông Nam, người chúng tôi gặp ở hội thảo, đã viết ba quyển sách.)","Whom dùng ở vị trí tân ngữ, mang giọng trang trọng; văn nói thường dùng who."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Mệnh đề xác định và không xác định"},{"table":[["Loại mệnh đề","Đặc điểm","Ví dụ"],["xác định","thông tin cần thiết, không dấu phẩy, dùng được that","The man who called is waiting."],["không xác định","thông tin phụ, có dấu phẩy, không dùng that","Mr Nam, who called earlier, is waiting."],["which bình luận","trỏ về cả mệnh đề trước","He forgot again, which is typical."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: My brother, that lives in Hue, is a teacher. → Đã sửa: My brother, who lives in Hue, is a teacher. — Mệnh đề không xác định không dùng that."},{"p":"Chưa đúng: My brother who lives in Hue is a teacher, and I only have one brother. → Đã sửa: My brother, who lives in Hue, is a teacher. — Thông tin phụ về một đối tượng đã xác định phải được tách bằng dấu phẩy."},{"p":"Chưa đúng: The book, I bought yesterday, is excellent. → Đã sửa: The book, which I bought yesterday, is excellent. — Mệnh đề không xác định không được lược bỏ đại từ quan hệ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Đối tượng đã được xác định rõ hay chưa."},{"p":"Mệnh đề được tách bằng dấu phẩy đầy đủ."},{"p":"Không dùng that trong mệnh đề không xác định."},{"p":"Đại từ quan hệ không bị lược bỏ."}]}],"id":"b2-12"},{"n":13,"title":"Emphasis with auxiliary do","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Trong câu khẳng định thông thường, động từ thường không cần trợ động từ. Nhưng khi người nói muốn khẳng định lại một điều bị nghi ngờ, muốn bày tỏ sự tương phản hoặc muốn nhấn giọng trong lời mời và lời đề nghị, tiếng Anh thêm do, does hoặc did vào trước động từ chính. Khi đó trợ động từ mang toàn bộ dấu hiệu về thì và ngôi, còn động từ chính trở về dạng nguyên mẫu."},{"p":"Cấu trúc chính: S + do/does/did + V nguyên mẫu"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I do understand your point, but I cannot agree. (Khẳng định lại điều bị nghi ngờ | Nêu tương phản | Nhấn giọng trong lời mời và lời đề nghị)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Khẳng định lại điều bị nghi ngờ: Dùng khi người nghe tỏ ra không tin hoặc đã nói điều ngược lại. (I did send the email — check your spam folder.)"},{"p":"Nêu tương phản: Thường đi với but hoặc although để nhượng bộ một phần rồi phản biện. (She does work hard, but she is often late.)"},{"p":"Nhấn giọng trong lời mời và lời đề nghị: Do cộng động từ nguyên mẫu làm lời mời nghe nồng nhiệt hơn. (Do come in. / Do have some more cake.)"},{"p":"Nhấn mạnh trong văn viết trang trọng: Dùng để làm nổi bật một luận điểm giữa mạch lập luận. (The data do suggest a trend, though the sample is small.)"},{"p":"Ghi nhớ: Thêm do, does hoặc did vào câu khẳng định để nhấn mạnh rằng điều đó có thật."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + do/does/did + V nguyên mẫu"},{"table":[["Trường hợp","Công thức / Quy tắc","Ví dụ"],["Hiện tại","I/you/we/they + do + V | he/she/it + does + V","He does know the answer."],["Quá khứ","S + did + V nguyên mẫu","I did tell you."],["Mệnh lệnh nhấn mạnh","Do + V nguyên mẫu","Do sit down."],["Với to be và động từ khuyết thiếu","không dùng do; nhấn bằng cách đọc mạnh hoặc thêm trạng từ","She is right. / He can swim."],["What-cleft","What + mệnh đề khuyết + be + phần được nhấn","What surprised the reviewers was the size of the effect."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn do, does hoặc did theo chủ ngữ: Trợ động từ mang dấu hiệu thì và ngôi. (she does ↔ they do ↔ I did)"},{"p":"02. Đưa động từ chính về dạng nguyên mẫu: Mọi dấu hiệu về thì đã chuyển sang trợ động từ. (did send, không phải did sent)"},{"p":"03. Kiểm tra to be và động từ khuyết thiếu: Hai nhóm này không dùng do để nhấn mạnh. (I am tired (không nói I do am tired))"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Nhượng bộ rồi phản biện","I do understand your point, but I cannot agree with the conclusion.\n(Tôi hiểu ý bạn, nhưng tôi không đồng ý với kết luận.)","Do nhấn rằng việc hiểu là có thật, nhờ đó phần phản biện ở sau nghe công bằng hơn."],["Khẳng định lại","I did send the email — please check your spam folder.\n(Tôi đã gửi email rồi, bạn kiểm tra hộp thư rác xem.)","Did dùng khi người nghe tỏ ra không tin; động từ chính trở về dạng nguyên mẫu send."],["Tương phản","She does work hard, but she is often late.\n(Cô ấy làm việc chăm thật, nhưng hay đến muộn.)","Does mang đuôi của ngôi thứ ba số ít, nên work giữ dạng nguyên mẫu."],["Lời mời","Do come in and have some tea.\n(Mời bạn vào uống chút trà.)","Do trước câu mệnh lệnh làm lời mời nghe nồng nhiệt hơn."],["Văn viết trang trọng","The data do suggest an upward trend, though the sample is small.\n(Dữ liệu cho thấy có xu hướng tăng, dù mẫu còn nhỏ.)","Data được dùng như danh từ số nhiều nên đi với do; cấu trúc này làm nổi bật luận điểm."],["Trả lời ngắn nhấn mạnh","You don't like coffee, do you? — I do like coffee, actually.\n(Bạn không thích cà phê à? — Thật ra tôi có thích.)","Do dùng để phản bác giả định trong câu hỏi."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba cách nhấn mạnh một khẳng định"},{"table":[["Cấu trúc","Chức năng","Ví dụ"],["do + V","nhấn rằng điều đó có thật","I do remember her."],["câu chẻ","nhấn một thành phần cụ thể","It was her that I remembered."],["đảo ngữ phủ định","nhấn sự hiếm có","Never have I seen that."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I do understood your point. → Đã sửa: I do understand your point. — Trợ động từ do đã mang dấu hiệu thì nên động từ chính về dạng nguyên mẫu."},{"p":"Chưa đúng: She do work hard. → Đã sửa: She does work hard. — Ngôi thứ ba số ít dùng does."},{"p":"Chưa đúng: I do am tired. → Đã sửa: I am tired. — Động từ to be không dùng do để nhấn mạnh."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Trợ động từ do, does hoặc did chọn đúng theo chủ ngữ và thì."},{"p":"Động từ chính ở dạng nguyên mẫu."},{"p":"Không dùng do với động từ to be và động từ khuyết thiếu."},{"p":"Sắc thái nhấn mạnh phù hợp với ngữ cảnh."}]}],"id":"b2-13"},{"n":14,"title":"Whatever, however & no matter","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Nhóm cấu trúc này nêu rằng kết quả giữ nguyên bất kể điều kiện thay đổi thế nào. Chúng gồm hai họ song song: các từ kết thúc bằng -ever và các cụm bắt đầu bằng no matter. Hai họ gần như thay thế nhau được, nhưng chỉ nhóm -ever mới dùng được ở vị trí chủ ngữ hoặc tân ngữ của một mệnh đề danh ngữ. Vì đây là mệnh đề chứ không phải câu hỏi, trật tự luôn là chủ ngữ trước động từ."},{"p":"Cấu trúc chính: whatever/whoever/however + mệnh đề | no matter what/who/how + mệnh đề"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Whatever you decide, I will support you. (Nêu kết quả không đổi | Nhấn mạnh mức độ | Khi đối tượng không quan trọng)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu kết quả không đổi: Mệnh đề nhượng bộ đứng trước, mệnh đề chính nêu kết quả. (Whatever happens, stay calm.)"},{"p":"Nhấn mạnh mức độ: However cộng tính từ hoặc trạng từ rồi mới đến chủ ngữ và động từ. (However hard he tried, he could not open it.)"},{"p":"Khi đối tượng không quan trọng: No matter what, no matter who, no matter how dùng thay nhóm -ever. (No matter who calls, say I am busy.)"},{"p":"Làm thành phần của câu: Whatever và whoever cũng làm chủ ngữ hoặc tân ngữ như một mệnh đề danh ngữ. (Whoever arrives first should open the hall.)"},{"p":"Ghi nhớ: Whatever, whoever, however và no matter what nêu rằng kết quả không đổi dù điều kiện thế nào."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: whatever/whoever/however + mệnh đề | no matter what/who/how + mệnh đề"},{"table":[["Nhóm cấu trúc","Từ / Công thức","Ví dụ"],["Nhóm -ever","whatever, whoever, whichever, wherever, whenever, however","Wherever you go, I will find you."],["Nhóm no matter","no matter what/who/which/where/when/how + mệnh đề","No matter where you go…"],["however + tính từ","however + adj/adv + S + V","however difficult it seems"],["Làm thành phần câu","whatever/whoever + mệnh đề, làm chủ ngữ hoặc tân ngữ","Take whatever you need."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn từ theo loại thông tin không xác định: Vật dùng whatever, người dùng whoever, cách thức và mức độ dùng however, nơi chốn dùng wherever. (whoever asks / however late)"},{"p":"02. Giữ trật tự chủ ngữ trước động từ: Cấu trúc này là mệnh đề nhượng bộ chứ không phải câu hỏi, nên không đảo trật tự và không dùng trợ động từ. (whatever you decide, không phải whatever do you decide)"},{"p":"03. Đặt tính từ ngay sau however: Trật tự là however cộng tính từ hoặc trạng từ, rồi mới đến chủ ngữ. (however hard he tried)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Kết quả không đổi","Whatever you decide, I will support you.\n(Bạn quyết định thế nào tôi cũng ủng hộ.)","Trật tự là whatever cộng chủ ngữ you cộng động từ decide, không có trợ động từ."],["Nhấn mạnh mức độ","However hard he tried, he could not open the door.\n(Anh ấy cố thế nào cũng không mở được cửa.)","Tính từ hard đứng ngay sau however, rồi mới đến chủ ngữ he."],["Nhóm no matter","No matter who calls, tell them I am in a meeting.\n(Ai gọi thì cũng nói là tôi đang họp.)","No matter who tương đương whoever trong vai trò mệnh đề nhượng bộ."],["Chỉ nơi chốn","Wherever you go in this city, you will find good food.\n(Đi đâu trong thành phố này bạn cũng tìm được món ngon.)","Wherever nêu rằng nơi chốn không làm thay đổi kết quả."],["Làm tân ngữ","Take whatever you need from the cupboard.\n(Bạn lấy gì cần trong tủ cũng được.)","Ở đây whatever làm tân ngữ của take chứ không mở đầu mệnh đề nhượng bộ."],["Làm chủ ngữ","Whoever arrives first should open the hall.\n(Ai đến trước thì mở hội trường.)","Whoever arrives first là mệnh đề làm chủ ngữ và kéo theo động từ số ít."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai họ cấu trúc song song"},{"table":[["Nhóm -ever","Tương đương","Ví dụ"],["whatever","= no matter what","Whatever happens, call me."],["whoever","= no matter who","Whoever asks, say nothing."],["however + adj","= no matter how + adj","However late it is, call me."],["chỉ nhóm -ever","làm được chủ ngữ hoặc tân ngữ của câu","Take whatever you want."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Whatever do you decide, I will support you. → Đã sửa: Whatever you decide, I will support you. — Mệnh đề nhượng bộ không dùng trợ động từ và không đảo trật tự."},{"p":"Chưa đúng: However he tried hard, he could not open it. → Đã sửa: However hard he tried, he could not open it. — Tính từ hoặc trạng từ phải đứng ngay sau however."},{"p":"Chưa đúng: No matter what will you say, I won't change my mind. → Đã sửa: No matter what you say, I won't change my mind. — Mệnh đề nhượng bộ không dùng will."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Từ được chọn khớp với loại thông tin không xác định."},{"p":"Trật tự là chủ ngữ trước động từ, không có trợ động từ."},{"p":"Tính từ đứng ngay sau however."},{"p":"Mệnh đề nhượng bộ không dùng will."},{"p":"Dùng whether hoặc if cho câu hỏi có hay không được thuật lại."}]}],"id":"b2-14"},{"n":15,"title":"Double & multiple comparisons","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Nhóm cấu trúc này diễn tả quan hệ giữa hai mức độ; phép so sánh cơ bản chỉ xếp hạng hai đối tượng. So sánh kép cho biết khi một yếu tố tăng thì yếu tố kia cũng thay đổi theo. So sánh gấp bội nêu tỉ lệ cụ thể. Cấu trúc tăng tiến lặp lại dạng so sánh hơn để diễn tả sự thay đổi liên tục."},{"p":"Cấu trúc chính: the + so sánh hơn, the + so sánh hơn | twice as … as"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The more you practise, the better you get. (Nêu quan hệ tỉ lệ giữa hai yếu tố | Nêu tỉ lệ gấp bội | Diễn tả sự thay đổi liên tục)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu quan hệ tỉ lệ giữa hai yếu tố: Hai vế đều bắt đầu bằng the và đều ở dạng so sánh hơn. (The higher you climb, the colder it gets.)"},{"p":"Nêu tỉ lệ gấp bội: Twice, three times, half đứng trước cấu trúc as … as. (This flat is twice as expensive as mine.)"},{"p":"Diễn tả sự thay đổi liên tục: Lặp lại dạng so sánh hơn và nối bằng and. (The queue got longer and longer.)"},{"p":"Nêu mức độ chênh lệch cụ thể: Dùng số từ hoặc cụm chỉ mức trước dạng so sánh hơn. (It is ten degrees colder today.)"},{"p":"Ghi nhớ: The + so sánh hơn, the + so sánh hơn diễn tả quan hệ tỉ lệ; twice as … as diễn tả gấp bội."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: the + so sánh hơn, the + so sánh hơn | twice as … as"},{"table":[["Loại so sánh","Công thức","Ví dụ"],["So sánh kép","The + so sánh hơn + mệnh đề, the + so sánh hơn + mệnh đề","The more he explained, the less I understood."],["Gấp bội","twice / three times / half + as + adj + as","half as long as the first one"],["Tăng tiến","so sánh hơn + and + so sánh hơn","more and more difficult"],["Mức chênh lệch","much / far / slightly / a bit + so sánh hơn","far more useful"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Đặt the ở đầu cả hai vế: Thiếu the thì cấu trúc không còn đúng. (The more you practise, the better you get.)"},{"p":"02. Chọn dạng so sánh theo độ dài tính từ: Tính từ ngắn thêm -er, tính từ dài dùng more; trạng từ và danh từ cũng theo quy tắc này. (the more expensive / the cheaper)"},{"p":"03. Đặt từ chỉ tỉ lệ trước as … as: Twice, three times đứng trước as, không chen vào giữa. (twice as big as)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["So sánh kép","The more you practise, the better you get.\n(Càng luyện tập nhiều, bạn càng giỏi hơn.)","Cả hai vế đều có the và đều ở dạng so sánh hơn; thiếu the là lỗi phổ biến."],["Quan hệ ngược chiều","The more he explained, the less I understood.\n(Anh ấy càng giải thích, tôi càng ít hiểu.)","Less là dạng so sánh hơn mang nghĩa giảm, dùng song song với more."],["Gấp hai lần","This flat is twice as expensive as mine.\n(Căn hộ này đắt gấp đôi căn của tôi.)","Twice đứng trước as; giữa hai as là tính từ ở dạng nguyên."],["Một nửa","The second talk was half as long as the first one.\n(Bài nói thứ hai dài bằng một nửa bài đầu.)","Half cũng theo mẫu half as … as."],["Tăng tiến","The queue got longer and longer as the morning went on.\n(Hàng người cứ dài dần ra suốt buổi sáng.)","Lặp lại dạng so sánh hơn và nối bằng and để diễn tả thay đổi liên tục."],["Mức chênh lệch cụ thể","It is ten degrees colder today than it was yesterday.\n(Hôm nay lạnh hơn hôm qua mười độ.)","Cụm chỉ mức ten degrees đứng ngay trước dạng so sánh hơn."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba cấu trúc so sánh nâng cao"},{"table":[["Cấu trúc","Nghĩa","Ví dụ"],["the … the …","quan hệ tỉ lệ giữa hai yếu tố","The sooner, the better."],["twice / three times as … as","gấp bội","three times as fast as"],["-er and -er / more and more","thay đổi liên tục","more and more expensive"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: More you practise, better you get. → Đã sửa: The more you practise, the better you get. — Cả hai vế của so sánh kép đều phải có mạo từ the."},{"p":"Chưa đúng: This flat is twice more expensive than mine. → Đã sửa: This flat is twice as expensive as mine. — Cấu trúc gấp bội dùng as … as, không dùng more … than."},{"p":"Chưa đúng: The queue got more long and more long. → Đã sửa: The queue got longer and longer. — Long là tính từ ngắn nên dùng dạng -er khi lặp lại."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Cả hai vế của so sánh kép đều có mạo từ the."},{"p":"Dạng so sánh hơn phù hợp với độ dài của tính từ."},{"p":"Cấu trúc gấp bội dùng as … as, không dùng more … than."},{"p":"Cấu trúc tăng tiến lặp lại đúng dạng so sánh hơn."},{"p":"So sánh nhất dùng the most với tính từ dài."}]}],"id":"b2-15"},{"n":16,"title":"Phrasal verbs & dependent prepositions","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Giới từ đi kèm là thành phần cố định của từ, không suy ra được từ nghĩa và không dịch được từng chữ từ tiếng Việt. Cụm động từ thì gồm động từ cộng một hoặc hai tiểu từ, và nghĩa của cả cụm thường khác hẳn nghĩa động từ gốc. Với cụm động từ có tân ngữ, cần biết cụm đó tách được hay không."},{"p":"Cấu trúc chính: depend on | interested in | look after"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The result depends on how hard you work. (Động từ có giới từ cố định | Tính từ có giới từ cố định | Cụm động từ mang nghĩa mới)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Động từ có giới từ cố định: Depend on, listen to, wait for, belong to, apologise for. (We are waiting for the results.)"},{"p":"Tính từ có giới từ cố định: Interested in, good at, afraid of, famous for, proud of. (She is good at solving problems.)"},{"p":"Cụm động từ mang nghĩa mới: Nghĩa của cả cụm không suy ra được từ động từ gốc. (give up = bỏ, từ bỏ / look after = chăm sóc)"},{"p":"Cụm động từ tách được hoặc không tách được: Cụm tách được cho phép tân ngữ chen vào giữa; đại từ thì bắt buộc chen vào giữa. (turn the light off / turn it off)"},{"p":"Ghi nhớ: Nhiều động từ và tính từ đòi hỏi một giới từ cố định; cụm động từ có nghĩa khác hẳn động từ gốc."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: depend on | interested in | look after"},{"table":[["Nhóm cấu trúc","Quy tắc vị trí","Ví dụ"],["Động từ + giới từ","không tách được, luôn có tân ngữ sau giới từ","look after the children / look after them"],["Động từ + tiểu từ (tách được)","V + O + tiểu từ hoặc V + tiểu từ + O","put off the meeting / put the meeting off"],["Đại từ làm tân ngữ","bắt buộc đứng giữa với cụm tách được","put it off, không phải put off it"],["Cụm ba phần","V + tiểu từ + giới từ, không tách","look forward to, put up with, get on with"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Học động từ cùng giới từ của nó: Không suy giới từ từ tiếng Việt vì hai ngôn ngữ không tương ứng. (depend on, không phải depend of)"},{"p":"02. Dùng V-ing sau giới từ: Mọi giới từ đều đòi hỏi V-ing, kể cả giới từ to trong look forward to. (interested in learning)"},{"p":"03. Kiểm tra cụm có tách được hay không: Cụm động từ cộng giới từ thì không tách; cụm động từ cộng tiểu từ thì tách được và đại từ phải chen vào giữa. (turn it on / listen to it)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Giới từ cố định","The result depends on how hard you work.\n(Kết quả phụ thuộc vào việc bạn làm việc chăm chỉ đến đâu.)","Depend luôn đi với on; depend of là lỗi do dịch từng chữ."],["Tính từ có giới từ","She is very good at solving problems.\n(Cô ấy rất giỏi giải quyết vấn đề.)","Good at là cụm cố định và sau giới từ at phải là V-ing."],["Cụm động từ nghĩa mới","He gave up smoking two years ago.\n(Hai năm trước anh ấy bỏ thuốc.)","Give up mang nghĩa từ bỏ, khác hẳn nghĩa của give."],["Cụm tách được","They put the meeting off until Monday.\n(Họ hoãn cuộc họp đến thứ Hai.)","Put off tách được nên tân ngữ danh từ đứng được ở giữa hoặc sau cụm."],["Đại từ chen vào giữa","The meeting was inconvenient, so they put it off.\n(Cuộc họp không thuận tiện nên họ hoãn lại.)","Với cụm tách được, đại từ làm tân ngữ bắt buộc đứng giữa."],["Cụm ba phần","I am looking forward to hearing from you.\n(Tôi mong nhận được tin của bạn.)","Look forward to không tách và chữ to là giới từ nên theo sau là V-ing."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Những giới từ người Việt hay dùng sai"},{"table":[["Cụm cố định","Nghĩa","Ví dụ"],["depend on","phụ thuộc vào","It depends on the weather."],["listen to / wait for","nghe / chờ","Wait for me, please."],["good at / interested in /afraid of","giỏi về / quan tâm đến / sợ","afraid of flying"],["married to / similar to /different from","kết hôn với / giống / khác","She is married to a teacher."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The result depends of how hard you work. → Đã sửa: The result depends on how hard you work. — Depend đi với giới từ on."},{"p":"Chưa đúng: She is good in solving problems. → Đã sửa: She is good at solving problems. — Good đi với giới từ at."},{"p":"Chưa đúng: The meeting was inconvenient, so they put off it. → Đã sửa: The meeting was inconvenient, so they put it off. — Với cụm động từ tách được, đại từ làm tân ngữ phải đứng giữa."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Giới từ đi kèm đã đúng với động từ hoặc tính từ đó."},{"p":"Sau giới từ là V-ing hoặc danh từ."},{"p":"Cụm động từ có tách được hay không."},{"p":"Đại từ làm tân ngữ đặt đúng vị trí trong cụm tách được."}]}],"id":"b2-16"}];
